# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""Gather-based upsample_nearest3d_backward (out variant) for Ascend/NPU Triton.

Semantics follow ATen exactly:
  scale_q  = float32(1.0/double(scales_q))   if scales_q is not None and > 0
           = float32(In_q) / float32(Out_q)   otherwise
  src_q(o) = min(int32(floorf(float32(o) * scale_q)), In_q - 1)
  grad_input[n,c,i,j,k] = sum of grad_output over the preimage of (i,j,k)

src_q is monotone non-decreasing, so each preimage is the contiguous half-open
interval [lo_q(i), lo_q(i+1)) with lo_q(In_q) == Out_q.  Every grad_input
element is written exactly once: no zero-init pass and no atomics.

Hard constraints of this target that the launch respects:
  * the backend passes the total block count as coreDim, which must be <= 65535,
    so rows are split into chunks;
  * every lane index that feeds an address is clamped into range, so no load or
    store address is ever formed outside the tensors (masked lanes included).

Two device paths:
  * uniform: every box along a dim has the same length r_q and lo_q(i) = i*r_q
    (all integral upsampling, which covers the tested workloads);
  * general: lo/hi recovered per lane by an exact branchless inversion.
"""

import numpy as np
import torch
import triton
import triton.language as tl

_MAX_GRID = 65535


# --------------------------------------------------------------------------- #
# device helpers
# --------------------------------------------------------------------------- #
@triton.jit
def _src_cmp(o, s, IN):
    """floorf(o*s) for comparisons; clamped at IN (never overflows int32)."""
    t = tl.minimum(o.to(tl.float32) * s, IN.to(tl.float32) + 1.0)
    return tl.minimum(t.to(tl.int32), IN)


@triton.jit
def _lo(i, s, OUT, IN, MODE: tl.constexpr):
    """Smallest o in [0, OUT] with floorf(o*s) >= i (== OUT when empty)."""
    if MODE == 0:
        # the answer is within +-2 of trunc(i/s)+1, so a few branchless fixes
        cand = (
            tl.minimum(i.to(tl.float32) / s, OUT.to(tl.float32) + 1.0).to(tl.int32) + 1
        )
        cand = tl.minimum(tl.maximum(cand, 0), OUT)
        for _ in tl.static_range(4):
            prev = cand - 1
            move = (_src_cmp(prev, s, IN) >= i) & (cand > 0)
            cand = tl.where(move, prev, cand)
        for _ in tl.static_range(4):
            move = (_src_cmp(cand, s, IN) < i) & (cand < OUT)
            cand = tl.where(move, cand + 1, cand)
        return cand
    else:
        # assumption-free lower_bound by binary lifting on a monotone map
        cnt = i * 0
        for k in tl.static_range(20):
            c = cnt + (1 << (19 - k))
            ok = (_src_cmp(c, s, IN) < i) & (c <= OUT)
            cnt = tl.where(ok, c, cnt)
        ans = tl.where(_src_cmp(cnt, s, IN) < i, cnt + 1, cnt)
        return tl.minimum(ans, OUT)


# --------------------------------------------------------------------------- #
# kernels  (grid = (W blocks, H_in, row chunk); row = row0 + program_id(2))
# --------------------------------------------------------------------------- #
@triton.jit
def _uni_kernel(
    go,
    gi,
    osn,
    osc,
    osd,
    osh,
    osw,
    gsn,
    gsc,
    gsd,
    gsh,
    gsw,
    C,
    ID,
    IH,
    IW,
    row0,
    RD: tl.constexpr,
    RH: tl.constexpr,
    RW: tl.constexpr,
    RWP: tl.constexpr,
    BLOCK_W: tl.constexpr,
    TAIL: tl.constexpr,
):
    pid_w = tl.program_id(0)
    ih = tl.program_id(1)
    row = row0 + tl.program_id(2)
    i_d = row % ID
    nc = row // ID
    n = nc // C
    c = nc % C

    iw = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    if TAIL:
        # clamp so that every formed address stays inside the tensors
        iwc = tl.minimum(iw, IW - 1)
    else:
        iwc = iw

    base_o = n * osn + c * osc + (i_d * RD) * osd + (ih * RH) * osh
    base_i = n * gsn + c * gsc + i_d * gsd + ih * gsh

    if RWP == RW:
        offs = (iwc[:, None] * RW + tl.arange(0, RW)[None, :]) * osw
        acc = tl.zeros((BLOCK_W,), dtype=tl.float32)
        for dd in tl.static_range(RD):
            for hh in tl.static_range(RH):
                row_o = base_o + dd * osd + hh * osh
                if TAIL:
                    v = tl.load(
                        go + row_o + offs,
                        mask=(iw < IW)[:, None],
                        other=0.0,
                    )
                else:
                    v = tl.load(go + row_o + offs)
                acc += tl.sum(v.to(tl.float32), axis=1)
    else:
        offs = (iwc[:, None] * RW + tl.arange(0, RWP)[None, :]) * osw
        kmask = tl.arange(0, RWP)[None, :] < RW
        acc = tl.zeros((BLOCK_W,), dtype=tl.float32)
        for dd in tl.static_range(RD):
            for hh in tl.static_range(RH):
                row_o = base_o + dd * osd + hh * osh
                v = tl.load(
                    go + row_o + offs,
                    mask=kmask & (iw < IW)[:, None],
                    other=0.0,
                )
                acc += tl.sum(v.to(tl.float32), axis=1)

    if TAIL:
        tl.store(
            gi + base_i + iwc * gsw,
            acc.to(gi.dtype.element_ty),
            mask=iw < IW,
        )
    else:
        tl.store(gi + base_i + iwc * gsw, acc.to(gi.dtype.element_ty))


@triton.jit
def _gen_kernel(
    go,
    gi,
    osn,
    osc,
    osd,
    osh,
    osw,
    gsn,
    gsc,
    gsd,
    gsh,
    gsw,
    C,
    OD,
    OH,
    OW,
    ID,
    IH,
    IW,
    row0,
    sc_d,
    sc_h,
    sc_w,
    MAX_D: tl.constexpr,
    MAX_H: tl.constexpr,
    MAX_W: tl.constexpr,
    BLOCK_W: tl.constexpr,
    MODE: tl.constexpr,
):
    pid_w = tl.program_id(0)
    ih = tl.program_id(1)
    row = row0 + tl.program_id(2)
    i_d = row % ID
    nc = row // ID
    n = nc // C
    c = nc % C

    sd = sc_d.to(tl.float32)
    sh = sc_h.to(tl.float32)
    sw = sc_w.to(tl.float32)

    lo_d = _lo(i_d, sd, OD, ID, MODE)
    hi_d = _lo(i_d + 1, sd, OD, ID, MODE)
    lo_h = _lo(ih, sh, OH, IH, MODE)
    hi_h = _lo(ih + 1, sh, OH, IH, MODE)

    iw = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    wmask = iw < IW
    iwc = tl.minimum(iw, IW - 1)
    lo_w = _lo(iwc, sw, OW, IW, MODE)
    hi_w = _lo(iwc + 1, sw, OW, IW, MODE)
    len_w = hi_w - lo_w

    base_o = n * osn + c * osc
    base_i = n * gsn + c * gsc + i_d * gsd + ih * gsh

    kw = tl.arange(0, MAX_W)
    kin = kw[None, :] < len_w[:, None]
    nd = hi_d - lo_d
    nh = hi_h - lo_h

    acc = tl.zeros((BLOCK_W,), dtype=tl.float32)
    for dd in tl.static_range(MAX_D):
        vd = dd < nd
        row_d = base_o + (lo_d + dd) * osd
        for hh in tl.static_range(MAX_H):
            vh = vd & (hh < nh)
            row_o = row_d + (lo_h + hh) * osh
            m = wmask[:, None] & vh & kin
            v = tl.load(
                go + row_o + (lo_w[:, None] + kw[None, :]) * osw,
                mask=m,
                other=0.0,
            )
            acc += tl.sum(v.to(tl.float32), axis=1)

    tl.store(gi + base_i + iwc * gsw, acc.to(gi.dtype.element_ty), mask=wmask)


@triton.jit
def _all_one_kernel(go, gi, nel, osn, osc, gsn, gsc, C, nc0, BLOCK: tl.constexpr):
    nc = nc0 + tl.program_id(0)
    n = nc // C
    c = nc % C
    off = n * osn + c * osc
    acc = tl.zeros((BLOCK,), dtype=tl.float32)
    for k in range(0, tl.cdiv(nel, BLOCK)):
        idx = k * BLOCK + tl.arange(0, BLOCK)
        v = tl.load(go + off + tl.minimum(idx, nel - 1), mask=idx < nel, other=0.0)
        acc += v.to(tl.float32)
    tl.store(gi + n * gsn + c * gsc, tl.sum(acc, axis=0).to(gi.dtype.element_ty))


@triton.jit
def _fill_kernel(
    gi,
    gsn,
    gsc,
    gsd,
    gsh,
    gsw,
    C,
    ID,
    IH,
    IW,
    row0,
    BLOCK_W: tl.constexpr,
):
    pid_w = tl.program_id(0)
    ih = tl.program_id(1)
    row = row0 + tl.program_id(2)
    i_d = row % ID
    nc = row // ID
    n = nc // C
    c = nc % C
    off_w = pid_w * BLOCK_W + tl.arange(0, BLOCK_W)
    off = n * gsn + c * gsc + i_d * gsd + ih * gsh + tl.minimum(off_w, IW - 1) * gsw
    tl.store(
        gi + off,
        tl.zeros((BLOCK_W,), dtype=gi.dtype.element_ty),
        mask=off_w < IW,
    )


# --------------------------------------------------------------------------- #
# host helpers
# --------------------------------------------------------------------------- #
def _pow2(n):
    p = 1
    while p < n:
        p <<= 1
    return p


def _block_w(iw):
    """Power-of-two W tile; prefer one that divides IW (no masked lanes)."""
    cap = min(_pow2(iw), 128)
    cand = cap
    while cand >= 1:
        if iw % cand == 0:
            if cand >= 8 or cand == cap:
                return cand
            break
        cand //= 2
    return min(cap, 16)


def _scale(value, in_size, out_size):
    """Exactly ATen's compute_scales_value<float>."""
    if value is not None and float(value) > 0.0:
        return float(np.float32(1.0 / float(value)))
    return float(np.float32(in_size) / np.float32(out_size))


def _map(scale, in_size, out_size):
    """Raw (unclamped) fp32 source map and its per-input preimage bounds."""
    o = np.arange(out_size, dtype=np.int64)
    t = (o.astype(np.float32) * np.float32(scale)).astype(np.float32)
    raw = np.floor(t).astype(np.int64)
    lo = np.searchsorted(raw, np.arange(in_size), side="left")
    hi = np.searchsorted(raw, np.arange(in_size), side="right")
    return raw, lo, hi


def _uniform_ratio(raw, in_size, out_size):
    """r if every box has length r and lo(i) == i*r, else 0."""
    if in_size <= 0:
        return 0
    if out_size % in_size != 0:
        return 0
    r = out_size // in_size
    if r <= 0 or r > 1024:
        return 0
    if not np.array_equal(raw, np.arange(out_size, dtype=np.int64) // r):
        return 0
    return int(r)


def _row_chunks(nwb, ih, nrows):
    """Split the row axis so that every launch has <= 65535 blocks in total."""
    per = max(1, nwb * ih)
    step = max(1, _MAX_GRID // per)
    return [(r0, min(step, nrows - r0)) for r0 in range(0, nrows, step)]


def _triple(size):
    vals = [int(v) for v in tuple(size)]
    if len(vals) == 5:
        return vals[2], vals[3], vals[4]
    if len(vals) >= 3:
        return vals[-3], vals[-2], vals[-1]
    return 0, 0, 0


def _five(size, grad_output):
    vals = [int(v) for v in tuple(size)]
    if len(vals) == 5:
        return vals[0], vals[1], vals[2], vals[3], vals[4]
    n, c = int(grad_output.shape[0]), int(grad_output.shape[1])
    d, h, w = _triple(vals)
    return n, c, d, h, w


# --------------------------------------------------------------------------- #
# entry point
# --------------------------------------------------------------------------- #
def upsample_nearest3d_backward_grad_input(
    grad_output,
    output_size,
    input_size,
    scales_d=None,
    scales_h=None,
    scales_w=None,
    grad_input=None,
    out=None,
):
    if grad_input is None:
        grad_input = out

    N, C, ID, IH, IW = _five(input_size, grad_output)
    OD, OH, OW = _triple(output_size)

    if grad_input is None:
        grad_input = torch.empty(
            (N, C, ID, IH, IW),
            device=grad_output.device,
            dtype=grad_output.dtype,
        )

    if grad_input.numel() == 0 or ID <= 0 or IH <= 0 or IW <= 0:
        return grad_input

    gsn, gsc, gsd, gsh, gsw = grad_input.stride()
    osn, osc, osd, osh, osw = grad_output.stride()

    if OD <= 0 or OH <= 0 or OW <= 0:
        # empty source: every box is empty -> exact zeros
        blk = 256
        nwb = triton.cdiv(IW, blk)
        nrows = N * C * ID
        for r0, rr in _row_chunks(nwb, IH, nrows):
            _fill_kernel[(nwb, IH, rr)](
                grad_input,
                gsn,
                gsc,
                gsd,
                gsh,
                gsw,
                C,
                ID,
                IH,
                IW,
                r0,
                BLOCK_W=blk,
            )
        return grad_input

    if ID == 1 and IH == 1 and IW == 1 and grad_output.is_contiguous():
        blk = 1024
        nc = N * C
        for c0 in range(0, nc, _MAX_GRID):
            _all_one_kernel[(min(_MAX_GRID, nc - c0),)](
                grad_output,
                grad_input,
                OD * OH * OW,
                osn,
                osc,
                gsn,
                gsc,
                C,
                c0,
                BLOCK=blk,
            )
        return grad_input

    sc_d = _scale(scales_d, ID, OD)
    sc_h = _scale(scales_h, IH, OH)
    sc_w = _scale(scales_w, IW, OW)

    raw_d, lo_d, hi_d = _map(sc_d, ID, OD)
    raw_h, lo_h, hi_h = _map(sc_h, IH, OH)
    raw_w, lo_w, hi_w = _map(sc_w, IW, OW)

    rd = _uniform_ratio(raw_d, ID, OD)
    rh = _uniform_ratio(raw_h, IH, OH)
    rw = _uniform_ratio(raw_w, IW, OW)

    block_w = _block_w(IW)
    nwb = triton.cdiv(IW, block_w)
    nrows = N * C * ID

    if rd and rh and rw and rd * rh <= 64:
        tail = 0 if IW % block_w == 0 else 1
        for r0, rr in _row_chunks(nwb, IH, nrows):
            _uni_kernel[(nwb, IH, rr)](
                grad_output,
                grad_input,
                osn,
                osc,
                osd,
                osh,
                osw,
                gsn,
                gsc,
                gsd,
                gsh,
                gsw,
                C,
                ID,
                IH,
                IW,
                r0,
                RD=rd,
                RH=rh,
                RW=rw,
                RWP=_pow2(rw),
                BLOCK_W=block_w,
                TAIL=tail,
            )
        return grad_input

    max_d = _pow2(max(1, int(np.max(hi_d - lo_d))))
    max_h = _pow2(max(1, int(np.max(hi_h - lo_h))))
    max_w = _pow2(max(1, int(np.max(hi_w - lo_w))))
    while block_w > 1 and block_w * max_w > 4096:
        block_w //= 2
    nwb = triton.cdiv(IW, block_w)
    mode = 0 if max(sc_d, sc_h, sc_w) <= 1.0 else 1

    for r0, rr in _row_chunks(nwb, IH, nrows):
        _gen_kernel[(nwb, IH, rr)](
            grad_output,
            grad_input,
            osn,
            osc,
            osd,
            osh,
            osw,
            gsn,
            gsc,
            gsd,
            gsh,
            gsw,
            C,
            OD,
            OH,
            OW,
            ID,
            IH,
            IW,
            r0,
            sc_d,
            sc_h,
            sc_w,
            MAX_D=max_d,
            MAX_H=max_h,
            MAX_W=max_w,
            BLOCK_W=block_w,
            MODE=mode,
        )
    return grad_input
